/**
 * External function `local_nexusai_quiz_study_plan`.
 *
 * Personalized study plan: combines the student's quiz error history with
 * chat questions the material couldn't answer well, and returns a unified,
 * ranked list of weak topics.
 *
 * @package    local_nexusai
 * @copyright  2026 NexusAI Team — UCC
 * @license    https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

namespace local_nexusai\external;

defined('MOODLE_INTERNAL') || die();
require_once($GLOBALS['CFG']->libdir . '/externallib.php');

/**
 * Personalized study plan: combines the student's quiz error history with chat questions the
 * material couldn't answer well, and returns a unified, ranked list of weak topics.
 */
class quiz_study_plan extends \external_api {
    /**
     * Parameters for execute().
     *
     * @return \external_function_parameters
     */
    public static function execute_parameters(): \external_function_parameters {
        return new \external_function_parameters([
            'courseid' => new \external_value(PARAM_INT, 'Course ID', VALUE_REQUIRED),
            'days'     => new \external_value(PARAM_INT, 'Days back (1..365)', VALUE_DEFAULT, 30),
        ]);
    }

    /**
     * Return value for execute().
     *
     * @return \external_single_structure
     */
    public static function execute_returns(): \external_single_structure {
        return new \external_single_structure([
            'course_id' => new \external_value(PARAM_INT, 'Course ID'),
            'topics'    => new \external_multiple_structure(
                new \external_single_structure([
                    'topic'                => new \external_value(PARAM_RAW, 'Weak topic identified by the AI'),
                    'quiz_error_count'     => new \external_value(PARAM_INT, 'Quiz errors backing this topic'),
                    'gap_count'            => new \external_value(
                        PARAM_INT,
                        'Unanswered chat questions backing this topic'
                    ),
                    'reason'               => new \external_value(PARAM_RAW, 'Why it\'s a weak topic'),
                    'suggested_quiz_topic' => new \external_value(PARAM_RAW, 'Suggested topic to preload the quiz generator'),
                    // SP-13 (#323): real row IDs backing the topic — the "topic"
                    // text is generated by the LLM on every call and isn't a
                    // stable key, so dismissing the topic operates on these IDs
                    // (see quiz_study_plan_dismiss.php).
                    'quiz_error_ids'   => new \external_multiple_structure(
                        new \external_value(PARAM_ALPHANUMEXT, 'UUID of a quiz_errors row')
                    ),
                    'gap_question_ids' => new \external_multiple_structure(
                        new \external_value(PARAM_ALPHANUMEXT, 'UUID of an unanswered_questions row')
                    ),
                ])
            ),
        ]);
    }

    /**
     * Personalized study plan: combines the student's quiz error history with chat questions the
     * material couldn't answer well, and returns a unified, ranked list of weak topics.
     *
     * @param int $courseid Course ID
     * @param int $days Days back (1..365)
     * @return array
     */
    public static function execute(int $courseid, int $days = 30): array {
        global $USER;

        $params = self::validate_parameters(self::execute_parameters(), [
            'courseid' => $courseid,
            'days'     => $days,
        ]);

        $context = \context_course::instance($params['courseid']);
        self::validate_context($context);
        require_capability('local/nexusai:use', $context);
        \local_nexusai\local\course_guard::require_enabled((int) $params['courseid']);

        $days = max(1, min(365, (int) $params['days']));

        $client   = new backend_client();
        $response = $client->quiz_study_plan((int) $params['courseid'], (int) $USER->id, $days);

        return [
            'course_id' => (int) ($response['course_id'] ?? $params['courseid']),
            'topics'    => array_map(
                static fn(array $t): array => [
                    'topic'                => (string) ($t['topic'] ?? ''),
                    'quiz_error_count'     => (int) ($t['quiz_error_count'] ?? 0),
                    'gap_count'            => (int) ($t['gap_count'] ?? 0),
                    'reason'               => (string) ($t['reason'] ?? ''),
                    'suggested_quiz_topic' => (string) ($t['suggested_quiz_topic'] ?? ($t['topic'] ?? '')),
                    'quiz_error_ids'       => array_map('strval', $t['quiz_error_ids'] ?? []),
                    'gap_question_ids'     => array_map('strval', $t['gap_question_ids'] ?? []),
                ],
                $response['topics'] ?? []
            ),
        ];
    }
}
